    "sourceUrl": "https://www.kofia.or.kr/brd/m_96/view.do?seq=42541",
    "applyUrl": "http://www.hrasset.co.kr/bbs/board.php?bo_table=employ&wr_id=15",
    "deadlineUnknown": true,
